UPDATE products SET description='Relaxed carpenter jeans in deep indigo, with curved reinforced knee panels, utility pockets and contrast stitching.',updated_at=datetime('now') WHERE id='vn-street-switch' AND description='Extra baggy carpenter jeans with curved double knees.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='A black pleated midi skirt with orange and cobalt accents revealed through the pleats, finished with an asymmetric wrap waistband.',updated_at=datetime('now') WHERE id='vn-studio-drift' AND description='Women’s midi skirt with asymmetric wrap waistband. Original cobalt and burnt-orange abstract brush print on selected INNER pleat panels, sublimated before pleating. L printed envelope per insert 12 x 65 cm, top 8 cm below waist. Approve pleat registration; reveal colour in movement.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='A sleeveless ivory and black knit vest with raised portrait textures and asymmetric ribbed edges.',updated_at=datetime('now') WHERE id='vn-studio-echo' AND description='Boxy sleeveless sweater with asymmetric rib edges. Original abstract monochrome face silhouette, knitted front and back. L envelope 36 x 49 cm; start 7 cm below shoulder and stop above hem rib. Knit artwork into panels and grade chart individually, preserve face proportions. Approve knit-down.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='A cropped, collarless black leather jacket with angular panel construction and a silver front zip.',updated_at=datetime('now') WHERE id='vn-studio-facet' AND description='Cropped boxy collarless leather jacket. No graphic. Angular panel geometry and leather grain form the design.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
