UPDATE products SET description='An oversized petrol-blue tee with layered, curved graphic appliqués and dropped shoulders.',updated_at=datetime('now') WHERE id='vn-studio-impulse' AND description='Oversized dropped-shoulder tee. Original coral/ochre/ivory abstract screenprint beneath raised curved applique. L front envelope 38 x 38 cm, top 15 cm below HSP; back envelope 38 x 40 cm, top 12 cm below back neck. Grade art 95/98/100/103/106%. Approve original artwork separations and strike-off.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='An oversized long-sleeve rugby jersey with burgundy and petrol stripes, an ivory collar and bold 26 graphics.',updated_at=datetime('now') WHERE id='vn-studio-night-study' AND description='Oversized long-sleeve rugby jersey. Fragmented number 26 in ivory twill with tonal topstitch, front and back envelope each 32 x 29 cm in L, bottom 8 cm above hem, wrapping wearer right side. Place before assembly with panel registration. Use 2 mm edge stitch and original fragment geometry. Grade 95/98/100/103/106%.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='Relaxed burgundy track trousers with curved ivory side panels and black mesh knee inserts.',updated_at=datetime('now') WHERE id='vn-studio-relay' AND description='Relaxed straight-leg track trousers. No printed graphic. Curved contrasting panels and knee mesh are primary design features.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='A navy padded gilet with sweeping curved quilting, a stand collar and zipped front pockets.',updated_at=datetime('now') WHERE id='vn-studio-shelter' AND description='Hoodless lightly padded gilet, relaxed overlayer fit. No graphic. Sculpted curved quilting and orange pocket reveal supply detail. No thermal or waterproof rating claimed without testing.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
UPDATE products SET description='Forest-green fleece shorts with cream contour-line artwork and ochre side inserts. An elastic waistband and drawcord complete the relaxed shape.',updated_at=datetime('now') WHERE id='vn-studio-tideline' AND description='Relaxed shorts ending just above knee. Cream contour-line embroidery on wearer left front leg, L envelope 18 x 25 cm, top 9 cm below waistband; min 2 mm line spacing, soft backing. Do not embroider across pocket opening. Grade artwork 95/98/100/103/106%.' AND EXISTS(SELECT 1 FROM audit_r16_20261031_products a WHERE a.id=products.id);
